/**
 * The service's agent-facing tool copy, as the Node SDK hands it to a model.
 *
 * Generated by `scripts/sync_tool_docs.py` from the tool manifest, which
 * arrives with every export carrying the copy the hosted MCP server publishes.
 * The generator reads one checked-in copy of it; `client/src/gen/tools.json`
 * is the same bytes, which `scripts/verify_provenance.py` checks. Do not edit:
 * `make tool-docs-check` and a pre-commit hook fail on any difference, and the
 * next run puts it back.
 *
 * TypeScript keeps no doc comments at runtime, so the copy cannot be read back
 * out of the source that documents it: it has to be a module. Compiled in at
 * build time it is reachable from the ESM build, the CommonJS build and any
 * bundler alike, with no filesystem read and no JSON import assertion — and,
 * being checked in rather than read off the manifest on startup, the
 * description a model is handed stays reviewable in a diff.
 *
 * The manifest's `${tool:...}` markers are already resolved. An offered
 * operation is spelled as a model calls it, `memco_search`; one a bound
 * session has already answered — `list_domains`, `start_session` — keeps its
 * bare name, because prefixing it would name a tool that does not exist.
 * Nothing below carries a marker.
 *
 * What the manifest publishes and this module leaves behind, named so that
 * nothing is dropped in silence:
 *
 * - `rpc`, the method each tool maps to. `scripts/verify_provenance.py` already
 *   checks it against the contract.
 * - `annotations`, MCP transport hints, which the agent layer never reads.
 * - `title`, a short label with no caller here.
 * - the manifest's top-level `instructions`, because a briefing is built from
 *   the `DomainEntry` and `Instructions` the service returns, not from this.
 * - the parameters in `SDK_SHAPED`, for the reason given there.
 */

/** One operation's copy: what it is for, and what each parameter means. */
export interface ToolCopy {
  /** What the operation is for, as a model should read it. */
  readonly description: string
  /**
   * One description per parameter the manifest names, keyed as this SDK spells
   * it: aliased, then camelised, so `op_id` is `operationId`.
   *
   * Every parameter the manifest names is here, including the ones a bound
   * session supplies itself. The generator does not know which those are; the
   * schema builder takes the subset its own method accepts.
   */
  readonly parameters: { readonly [name: string]: string }
}

/**
 * Prepended to each operation's name, so the tools are recognisable as a set.
 *
 * The keys of `TOOL_COPY` are the manifest's own names, so the name a model
 * calls is composed rather than stored and a change here is one constant.
 */
export const TOOL_PREFIX = 'memco_'

/**
 * The operations offered to a model, in the order a task uses them.
 *
 * Written out rather than read off the manifest. Everything a tool exposes
 * crosses into an untrusted model's reach, so an operation is offered because
 * someone decided it should be.
 */
export const OFFERED = [
  'search',
  'get_memory',
  'create_memory',
  'enrich_memory',
  'share_feedback',
  'revert_memory'
] as const

/**
 * Operations the copy names that a bound session has already answered.
 *
 * The service's copy is written for a caller who picks a domain and opens a
 * session per call, so it points at both — and it is right to, on the surface
 * it was written for. Neither is a tool here, which is why their markers are
 * spelled bare above and why a briefing has to say so.
 */
export const ANSWERED = ['list_domains', 'start_session'] as const

/**
 * The parameters this module leaves out, because this SDK's shape is not the
 * wire's.
 *
 * The manifest describes what the MCP server accepts: tags and feedback as
 * lists of XML elements, and a source as one of two bare literals. This SDK
 * takes its own types and builds a model an object schema from them, so the
 * wire copy would describe an encoding that schema does not accept — the one
 * case where the service's words are wrong for this surface. Their
 * descriptions are hand-written where the schema is built.
 */
export const SDK_SHAPED = ['feedback', 'source', 'tags'] as const

/**
 * Every tool the manifest publishes, by the manifest's own name for it.
 *
 * `as const satisfies Record<string, ToolCopy>` on purpose: the literal keys
 * survive, so a mistyped name is a compile error at the call site rather than
 * an undefined description handed to a model.
 */
export const TOOL_COPY = {
  create_memory: {
    description: `Save new knowledge to Memco Shared Memory, where your teammates and their agents will find it.
Call when: you have learned something non-obvious that would help your team — why something turned out the way it did, how something actually behaves, something that was hard to establish, or a decision and its rationale — or your user has corrected you. Search first: when a related memory already exists, memco_enrich_memory extends it instead of leaving a near-duplicate beside it.
Pass either a domain or a session_id — a call naming neither is refused. Naming the session you have been searching in saves the memory into that session's domain and records it as part of that work; naming a domain alone saves a standalone memory.
Each memory needs a query (what someone would search to find this), a title, and content describing what you learned. list_domains says what belongs in the chosen domain and which tags to use.`,
    parameters: {
      content: `(Required) The knowledge to save. Should be a concise, non-trivial finding that others can learn from. Supports markdown formatting. Title and content together must be at most 5000 characters; split a longer finding across several memories.`,
      domain: `The memory domain to save into. Required unless you pass session_id, which supplies the domain of the session it names. Call list_domains for the domains available to you.`,
      query: `(Required) A query describing what someone would search to find this memory, such as a question or problem statement. Use markdown formatting for readability. At most 1000 characters.`,
      sessionId: `The session this memory was learned during, as returned by start_session or a previous search. It records the memory as part of that series of work, and supplies the memory domain, so the domain argument is not needed and is ignored. Omit it to save a standalone memory.`,
      title: `(Required) A short title describing what this memory is about. Title and content together must be at most 5000 characters.`
    }
  },
  enrich_memory: {
    description: `Add information to an existing memory in Memco Shared Memory, so your finding lands beside the one it belongs to rather than in a memory that competes with it.
Call when: a search returned a memory close to what you learned but incomplete, out of date, or missing the approach you took. Use memco_create_memory instead when nothing returned covers the subject at all.
Set memory_idx to the memory you want to extend (from search results), or 'new' to add a standalone addition. Keep an addition concise and say only what is not already there. The addition lands in the domain the search session ran in; you do not name one.`,
    parameters: {
      content: `(Required) The knowledge you want to add. Use markdown formatting for readability. Title and content together must be at most 5000 characters; split a longer finding across several enrichments.`,
      memoryIdx: `(Required) The memory_idx of the memory you are enriching. If you are adding to a new memory, set memory_idx to 'new'.`,
      sessionId: `(Required) The session id you are enriching a memory in. The ID was included in the response from memco_search.`,
      sources: `A list of memories received from Memco Shared Memory that proved helpful in reaching this insight. Up to 20 sources can be included.`,
      title: `(Required) A short title describing what you learned. Title and content together must be at most 5000 characters.`
    }
  },
  get_memory: {
    description: `Fetch one memory a search returned, by its idx, and get it back in full.
Call when: you hold an idx whose content is not in front of you — a search returned the memory as a reference to an idx that carried it earlier, or another agent did the searching and passed you the handle. An insight's idx returns the memory holding it.
The idx is all it takes: copy it exactly as it appeared in a search response — it cannot be constructed by hand — and nothing else is needed to name the result.
When a result shows a ref instead of content, ask by the value in its own idx, never the value in its ref. A result rendered as <memory idx="memory-THIS-1" ref="memory-EARLIER-1"> is fetched with "memory-THIS-1": the ref says where the content was delivered, not what to ask for. Both return the same text, but only its own idx keeps a later rating with the search you are working in.`,
    parameters: {
      idx: `(Required) The idx of the result to fetch, copied exactly as it appeared in a search response. An insight's idx returns the memory holding it.`
    }
  },
  import_memories: {
    description: `Fill a new or nearly empty workspace with the knowledge a team already holds, in one call, so memory starts out useful instead of empty.
Call when: filling a workspace that has little or nothing in it, or onboarding someone into one — a teammate joining, or your own first connection to it. This is a setup step, done once: you are handing over what is already known, not recording something you just learned. Use memco_create_memory for a single finding from this session.
Pass either a domain or a session_id — a call naming neither is refused. Each memory needs at least one query describing what someone would search to find it, and at least one insight with a title and content. At most 25 memories per call, 20 queries and 10 insights each; send several calls for more.
Every memory is checked on the way in and starts at your own standing, exactly as a single write does. The response answers per memory, by the position you sent it in: one that was refused says why, and one whose content is already held says so and is not written again.`,
    parameters: {
      domain: `The memory domain to import into. Required unless you pass session_id, which supplies the domain of the session it names. Call list_domains for the domains available to you.`,
      memories: `(Required) The memories to contribute. At least one, at most 25 per call; send several calls for more.`,
      sessionId: `The session these memories were contributed during, as returned by start_session or a previous search. It records them as part of that series of work, and supplies the memory domain, so the domain argument is not needed and is ignored.`
    }
  },
  list_domains: {
    description: `List the memory domains available to you and describe each one: what it holds, when to search it, what belongs in it and what does not, and the tag vocabulary and format it uses.
Call when: before your first search or write of a task, and whenever you are unsure which domain a question or a finding belongs to. The slug you choose is what start_session, memco_search and memco_create_memory take as their domain argument.`,
    parameters: {}
  },
  revert_memory: {
    description: `Undo a memory you just wrote, using the operation id that memco_create_memory or memco_enrich_memory returned.
Call when: you saved something by mistake — wrong content, the wrong domain, or something that should not have been shared.
Your entry is always removed. The memory it belongs to is removed with it only when your entry was the last one in it — so reverting a memco_create_memory, or an memco_enrich_memory you sent with memory_idx 'new', removes that memory too, while reverting an addition to a memory that holds other entries leaves the memory in place. You can only revert your own writes, and only within 2 days.`,
    parameters: {
      operationId: `(Required) The operation id returned by the memco_create_memory or memco_enrich_memory call you want to undo, for example 'create-hpc08-1'.`
    }
  },
  search: {
    description: `Search Memco Shared Memory for existing knowledge before working a problem out from scratch. It holds what your teammates and their agents have already established and recorded.
Call when: you start a task, plan a non-trivial piece of work, meet something unfamiliar, hit a question you cannot answer from what you already know, or are about to reason out something a teammate may already have settled. Search first, then work.
Pass either a domain or a session_id — a search naming neither is refused. Naming a session runs the search in that session's domain and records it alongside the other searches made for the same task; naming a domain alone starts a session for this one search.
The query uses both keyword and semantic search, and is intended for a single concept per query. If you need varied information, make multiple queries.
Supply tags to narrow the results; list_domains lists the tag types the chosen domain uses and the format they take.
Results come back most-relevant-first and are bounded, so a search returns what fits rather than everything that matched; the response says what it left out. Memories are written by your teammates and their agents. Within one session a result already returned is not repeated — it comes back as a reference to the idx that carried it, which memco_get_memory turns back into content.`,
    parameters: {
      domain: `The memory domain to search in. Required unless you pass session_id, which supplies the domain of the session it names. Call list_domains for the domains available to you.`,
      query: `(Required) A task-based query from the user such as a question, statement, or task description. To ensure readability, use markdown formatting. At most 1000 characters.`,
      sessionId: `The session to record this search under, as returned by start_session or a previous search. The search runs in that session's memory domain, so the domain argument is not needed and is ignored. Omit this to start a new session, in which case a domain is required.`
    }
  },
  share_feedback: {
    description: `Rate the relevance and correctness of search results. Only you can tell whether a result answered the query, and these ratings shape which results are shown next.
Call when: you have read the results of a search and can judge them — once per search, while its session id is still to hand.
The feedback is recorded against the domain the search session ran in; you do not name one.`,
    parameters: {
      sessionId: `(Required) The session you are providing feedback for. The ID was included in the response from memco_search.`
    }
  },
  start_session: {
    description: `Start a session and get its id. A session groups the searches you make while working on one task, so they are recorded as the series they are rather than as unrelated one-offs.
Call when: at the start of work that will involve multiple related searches, or when you want a stable session id to reuse across memco_search, memco_share_feedback, and memco_enrich_memory. Pass the id as session_id to every search you make for it — and to memco_share_feedback and memco_enrich_memory. A session stays usable for as long as you keep naming it.`,
    parameters: {
      domain: `(Required) The memory domain to operate in. Call list_domains for the domains available to you.`
    }
  }
} as const satisfies Record<string, ToolCopy>

/**
 * The copy for the nested request fields of `import_memories`, by the
 * manifest's own path for each.
 *
 * Nothing here reaches a model — `import_memories` is not an offered tool. It
 * is carried so that every string the manifest publishes is either written
 * above or excluded by name, which is what makes "nothing was dropped"
 * something a reader can check rather than take on trust.
 */
export const NESTED_COPY = {
  'memories[].insights': `(Required) The findings this memory holds. At least one, at most 10.`,
  'memories[].insights[].content': `(Required) The knowledge to save. Should be a concise, non-trivial finding that others can learn from. Supports markdown formatting.`,
  'memories[].insights[].title': `(Required) A short title describing what this insight is about. Title and content together must be at most 5000 characters.`,
  'memories[].queries': `(Required) The queries someone would search to find this memory, such as questions or problem statements. At least one, at most 20.`
} as const satisfies Record<string, string>
